    --line: 14px;
  }
  * { box-sizing: border-box; margin: 0; }
  html { scroll-behavior: smooth; }
  body {
    font-family: "Archivo", "Helvetica Neue", Arial, sans-serif;
    background: var(--black); color: var(--black);
