  }
  /* Black ground shows through the gaps: the lines are the layout. */
  .canvas, .story {
    display: grid; gap: var(--line); background: var(--black);
    padding: var(--line); max-width: 1280px; margin: 0 auto;
  }
  .canvas { padding-bottom: 0; }
  .cell { background: var(--white); padding: clamp(1rem, 2.4vw, 2rem); min-width: 0; }
  .red { background: var(--red); color: #fff; }
  .blue { background: var(--blue); color: #fff; }
  .yellow { background: var(--yellow); }
  .grey { background: var(--grey); }
