  .c-why   { grid-column: 2; grid-row: 3 / 5; }
  .c-blank { grid-column: 3; grid-row: 3; min-height: 4rem; }
  .c-more  { grid-column: 3; grid-row: 4; padding: 0; display: flex; }
  .c-title .sub { margin-top: 1.2rem; font-size: clamp(1rem, 1.6vw, 1.3rem); font-weight: 600; }

  a { color: inherit; }
  .c-more a, .cta a {
    font-weight: 800; text-decoration: none; display: flex; align-items: flex-end;
    width: 100%; padding: clamp(1rem, 2vw, 1.5rem); min-height: 44px;
    transition: background .15s, color .15s;
  }
  .c-more a:hover, .cta a:hover { background: var(--black); color: var(--yellow); }
  a:focus-visible { outline: 4px solid var(--blue); outline-offset: -8px; }
  .red a:focus-visible, .blue a:focus-visible { outline-color: #fff; }

